/** <img> props for a city photo: srcset with the high-resolution copy, its real width and height, lazy loading. */
export function photoProps(src: string, sizes: string) {
  const size = photoSizes[src];
  if (!size) return { src, loading: 'lazy' as const, decoding: 'async' as const };
  return {
    src, width: size.w, height: size.h, loading: 'lazy' as const, decoding: 'async' as const,
    ...(size.w2 && { srcSet: `${src} ${size.w}w, ${src.replace(/\.webp$/, '-2x.webp')} ${size.w2}w`, sizes }),
  };
}
